import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
# Técnica 03 · Toracocentesis (borrador 25/11/2026). Fuentes: BTS Clinical Statement on pleural procedures 2023 (texto completo),
# SEPAR 2022 (actualización de la normativa de derrame pleural) y NEJM Videos in Clinical Medicine 2006.
T="TORACOCENTESIS"; N=7; KW=dict(strip=K)
note=lambda t: f'<div style="font-size:36px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:22px">'+"".join(x)+'</div>'
paso=lambda i,t: kicker(f"TÉCNICA 03 · PASO {i} DE 5")+big(t,118,R)
P=[
page(1,N,T,f'<div style="font-size:40px;font-weight:800;letter-spacing:6px;color:{Y}">TÉCNICA 03</div>'+big("TORACOCENTESIS",138,"#FFFFFF",True)+big(f'CON ECO Y <span style="color:{Y}">ENCIMA DE LA COSTILLA</span>',108,"#FFFFFF")+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Cinco pasos, qué muestras enviar y cuándo parar. Con ficha final.</div>',cover=True,dark=True,**KW),
page(2,N,T,paso(1,"ECOGRAFÍA PRIMERO")+'<div style="font-size:50px;font-weight:800;line-height:1.2">Marca el punto con ecografía, en la misma posición en la que vas a pinchar</div>'+rows(line("Sentado, inclinado hacia delante, con los brazos apoyados en una mesa"),line("Mide la distancia hasta la pleura y el grosor del derrame"))+note("Obligatoria salvo emergencia: reduce el neumotórax y la punción de otros órganos."),**KW),
page(3,N,T,paso(2,"ENCIMA DE LA COSTILLA")+'<div style="font-size:50px;font-weight:800;line-height:1.2">Pincha justo por encima del borde superior de la costilla inferior</div>'+rows(row("Por qué","El paquete vasculonervioso va por debajo de cada costilla"),row("Dónde","Lateral o posterolateral, nunca pegado a la columna"))+note("En la zona paravertebral la arteria intercostal no queda protegida por la costilla."),**KW),
page(4,N,T,paso(3,"ASEPSIA Y ANESTESIA")+rows(line("Antiséptico, campo y guantes estériles"),line("Lidocaína al 1 %: piel, borde superior de la costilla y pleura",True),line("Aspira mientras avanzas: si sale líquido, estás en la pleura"))+note("Lidocaína al 1 %: hasta 3 mg/kg (máximo 250 mg = 25 ml)."),**KW),
page(5,N,T,paso(4,"PUNCIÓN Y MUESTRAS")+rows(row("Diagnóstica","Aguja fina (21 G); unos 50 ml"),row("Evacuadora","Catéter de 6–8 F si vas a sacar más de 60 ml"),line("Llave de tres pasos para poder cerrar enseguida"))+note("Envía: proteínas, LDH y glucosa; pH en jeringa de gasometría; citología; cultivos y frascos de hemocultivo; ADA. Proteínas y LDH en sangre a la vez para aplicar los criterios de Light."),**KW),
page(6,N,T,paso(5,"SABER PARAR")+'<div style="font-size:50px;font-weight:800;line-height:1.2">Máximo 1,5 l por sesión, despacio, con jeringa o por gravedad</div>'+rows(line("Nunca botellas de vacío ni aspiración de pared"),line("Para si aparece tos persistente, opresión, dolor o más disnea"),f'<div style="border-top:4px solid {K};padding-top:22px;font-size:42px;font-weight:800;line-height:1.3;color:{R}">Edema de reexpansión: raro (&lt; 1 %) pero grave. Para, oxígeno y radiografía urgente</div>')+note("Radiografía de control solo si hay síntomas, complicaciones o varios intentos."),**KW),
page(7,N,T,ficha_body("TORACOCENTESIS","Adulto",[("ECOGRAFÍA","Obligatoria; marca en la posición de la punción",True),("POSICIÓN","Sentado, inclinado hacia delante, brazos apoyados"),("PUNTO","Borde superior de la costilla inferior; nunca paravertebral",True),("ANESTESIA","Lidocaína 1 % hasta 3 mg/kg (máx. 25 ml)"),("DIAGNÓSTICA","Aguja 21 G, ~50 ml: bioquímica, pH, citología, cultivos, ADA"),("EVACUADORA","Catéter si > 60 ml; máx. 1,5 l; sin vacío",True),("PARAR SI","Tos persistente, opresión, dolor o más disnea"),("ANTICOAG.","Programada: suspender (INR ≤ 1,5). Urgente: valora riesgo")],"Asciak R, et al. BTS Clinical Statement on pleural procedures. Thorax 2023;78(supl 3):s43-68",size=110,fs=27),ficha="03",fam="TÉCNICA",**KW),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","tecnica-toracocentesis")
